"""Detailed explanations with diagrams: HLD questions, part 5."""
from sd_x_util import X, P, H, AN, KEY, FLOW, SEQ, NOTE, ER, TABLE, CALC, BARS, CODE, UML, STATE

X("googledocs-hld",
  P("""**What the system does.** Several people type into the same document at once and everyone sees the same final text, with each other's cursors, within ~100 ms. The heart of it is **conflict resolution**: if Asha inserts at position 5 while Ravi deletes position 2, applying both naively gives different results on different screens. **Operational Transformation (OT)** or **CRDTs** fix that."""),
  AN("Two people editing a shared shopping list by phone. Ravi says 'delete line 2'; at the same moment Asha says 'insert milk at line 5'. After Ravi's delete, Asha's 'line 5' is now line 4. OT is the referee that rewrites Asha's instruction to 'insert at line 4' so both lists end up identical."),
  TABLE("OT in one example: text = \"HELLO\"", ["Step", "Asha (local)", "Ravi (local)", "Server (orders ops)"],
        [["1", "insert '!' at 5 → HELLO!", "delete at 0 → ELLO", ""], ["2", "", "", "receives Ravi's delete first: rev 1, text ELLO"],
         ["3", "", "", "Asha's op was based on rev 0; transform: insert at 5 → **insert at 4** (one char was removed before it)"], ["4", "receives delete(0) → ELLO!", "receives insert(4,'!') → ELLO!", "rev 2: ELLO!  ✔ everyone equal"]]),
  SEQ("Editing through the document's owner server", ["Editor A", "Editor B", "Collab server (doc owner)", "Op log"],
      [["Editor A", "Collab server (doc owner)", "op insert(5,'!') based on rev 0", "", "All editors of one doc are routed to the same server (consistent hashing on doc id), which holds the doc's state in memory and decides the order."],
       ["Editor B", "Collab server (doc owner)", "op delete(0) based on rev 0"], ["Collab server (doc owner)", "Op log", "append delete(0) as rev 1"],
       ["Collab server (doc owner)", "Collab server (doc owner)", "transform A's op against rev 1 → insert(4,'!')"], ["Collab server (doc owner)", "Op log", "append as rev 2"],
       ["Collab server (doc owner)", "Editor A", "ack rev 2 + delete(0)", "r"], ["Collab server (doc owner)", "Editor B", "insert(4,'!') rev 2", "r", "Cursors and presence are sent the same way but never stored."]]),
  TABLE("OT vs CRDT", ["", "OT (Google Docs)", "CRDT (Yjs, Automerge, Figma-like)"], [["needs a central server", "yes, orders ops", "no, merges in any order"], ["offline editing", "limited", "excellent"],
                                                                                   ["metadata overhead", "small", "per-character ids (larger)"], ["complexity", "transform functions are subtle", "data structure is subtle"]]),
  ER("Storage", [("ops", "Bigtable / Spanner", [("doc_id", "", "PK"), ("rev", "bigint", "PK"), ("op", "json", ""), ("author", "", ""), ("ts", "", "")], "Append-only; replaying from a snapshot rebuilds the doc."),
                 ("snapshots", "object storage", [("doc_id", "", "PK"), ("rev", "", "PK"), ("content", "blob", "")], "Every N ops, so loading needs snapshot + a few ops.")]))

X("searchengine-hld",
  P("""**What the system does.** Given a few words, return the 10 most relevant pages out of hundreds of billions, in ~200 ms, 100k times per second. Offline: crawl, build an **inverted index** (word → list of pages) and compute link-based quality (PageRank). Online: send the query to **every index shard in parallel** (scatter), merge their best results (gather), then re-rank."""),
  AN("The index at the back of a textbook, but for the whole web: look up 'consistent' and 'hashing', intersect their page lists, then order the pages by how well they match and how trustworthy they are (how many good books cite them)."),
  TABLE("Inverted index (tiny example)", ["Term", "Postings (doc id: positions)"], [["consistent", "d3: [4, 19], d7: [1], d9: [12]"], ["hashing", "d3: [5, 20], d9: [2]"], ["ring", "d3: [33], d5: [8]"]],
        "Query 'consistent hashing' → intersect → {d3, d9}; d3 has the words next to each other twice (positions 4–5, 19–20), so it scores higher."),
  FLOW("Scatter-gather query path", [["u:Users"], ["Query frontend (spell check, parse)"], ["Root aggregator (scatter-gather)"], ["Index shard 1", "Index shard 2", "Index shard …", "Index shard N"], ["db:Doc store (snippets)"]],
       [["Users", "Query frontend (spell check, parse)"], ["Query frontend (spell check, parse)", "Root aggregator (scatter-gather)"], ["Root aggregator (scatter-gather)", "Index shard 1"], ["Root aggregator (scatter-gather)", "Index shard 2"],
        ["Root aggregator (scatter-gather)", "Index shard …"], ["Root aggregator (scatter-gather)", "Index shard N"], ["Root aggregator (scatter-gather)", "Doc store (snippets)", "top 10"]],
       "Document-partitioned index: each shard indexes a slice of pages, so every query touches every shard but each does little work."),
  SEQ("One query", ["User", "Frontend", "Aggregator", "Shards (×1000)", "Doc store"],
      [["User", "Frontend", "q = 'consistnt hashing'"], ["Frontend", "Frontend", "spell-correct → 'consistent hashing'; check result cache", "", "Popular queries are answered from cache directly."],
       ["Frontend", "Aggregator", "search"], ["Aggregator", "Shards (×1000)", "top 50 for this query (deadline 80 ms)", "", "Hedged requests: if a replica is slow, ask another replica too and take the first answer (tail latency)."],
       ["Shards (×1000)", "Aggregator", "each: top 50 by BM25 + PageRank", "r"], ["Aggregator", "Aggregator", "merge 50,000 → top 100 → ML re-rank → top 10"], ["Aggregator", "Doc store", "titles + snippets for 10"],
       ["Aggregator", "User", "results page", "r"]]),
  TABLE("Ranking signals", ["Signal", "Meaning"], [["BM25", "how well the words match (term frequency, rarity, length normalisation)"], ["PageRank", "quality from links: a page linked by important pages is important"],
                                                  ["freshness", "recent pages for news-like queries"], ["learning to rank", "ML model combining hundreds of signals and click feedback"]]))

X("stockexchange-hld",
  P("""**What the system does.** Accepts buy and sell orders and **matches** them fairly and deterministically: best price first, then earliest time (price-time priority), with microsecond latency, and can **replay** every decision for audits. The surprising design: matching per symbol is **single-threaded** in memory, after a **sequencer** puts all orders into one total order."""),
  AN("An auctioneer for one item who listens to a single queue of bids through one door. Because only one person speaks at a time in a fixed order, the outcome is fair and can be replayed exactly from the recording (event log)."),
  TABLE("Order book for INFY (price-time priority)", ["BUY side (highest first)", "", "SELL side (lowest first)"],
        [["₹1,501 × 300 (09:15:01)", "", "₹1,502 × 200 (09:15:00)"], ["₹1,500 × 500 (09:15:02)", "", "₹1,503 × 400 (09:15:03)"], ["₹1,500 × 100 (09:15:05)", "", "₹1,505 × 1,000"]],
        "A new market BUY for 300 shares fills 200 @ ₹1,502 then 100 @ ₹1,503 (best prices first). At the same price, the earlier order fills first."),
  SEQ("Order → trade", ["Broker", "Gateway", "Sequencer", "Event log", "Matching engine (INFY)", "Market data"],
      [["Broker", "Gateway", "BUY INFY 300 @ market"], ["Gateway", "Gateway", "auth + pre-trade risk (limits, margin)"], ["Gateway", "Sequencer", "order"],
       ["Sequencer", "Event log", "append seq 98,231,004 (replicated)", "", "The total order is decided here. The log is the source of truth (event sourcing)."],
       ["Sequencer", "Matching engine (INFY)", "seq 98,231,004", "", "One thread per symbol shard, all in memory, no locks (LMAX Disruptor style)."],
       ["Matching engine (INFY)", "Matching engine (INFY)", "match: 200 @ 1,502, 100 @ 1,503"], ["Matching engine (INFY)", "Market data", "trades + book update", "a"], ["Matching engine (INFY)", "Broker", "fills", "r"]]),
  TABLE("Why this shape", ["Choice", "Reason"], [["sequencer + log", "determinism: the same input log always produces the same trades; hot standby replays the same log"], ["single thread per symbol", "no locks, predictable microsecond latency"],
                                                ["shard by symbol", "symbols are independent: scale out"], ["settlement separate", "clearing/settlement is a slower batch domain (T+1)"]]))

X("mq-hld",
  P("""**What the system does.** A durable, ordered, replayable message log at ~1 GB/s (Kafka). Producers append; consumers read at their own pace and can rewind. Throughput comes from **sequential disk writes, batching, the OS page cache and zero-copy**; durability from **replicating each partition** to followers in sync."""),
  AN("Each partition is a ship's logbook kept by a captain (leader) with two officers copying every line as it's written (followers in sync). Readers each keep a bookmark (offset). If the captain falls overboard, an officer whose copy is complete becomes captain."),
  CALC("Sizing", [("Ingest", "i = 1e6 * 1e3", "B/s"), ("7 days retained", "i * 86400 * 7", "B"), ("With replication 3", "i * 86400 * 7 * 3", "B"), ("Brokers at 50 TB usable each", "i * 86400 * 7 * 3 / 50e12", "")]),
  FLOW("Partitions, leaders and followers", [["Producers"], ["Broker 1 (P0 leader, P1 follower)", "Broker 2 (P1 leader, P2 follower)", "Broker 3 (P2 leader, P0 follower)"], ["Consumer group A", "Consumer group B"]],
       [["Producers", "Broker 1 (P0 leader, P1 follower)", "key → P0"], ["Producers", "Broker 2 (P1 leader, P2 follower)", "key → P1"], ["Producers", "Broker 3 (P2 leader, P0 follower)", "key → P2"],
        ["Broker 1 (P0 leader, P1 follower)", "Consumer group A"], ["Broker 2 (P1 leader, P2 follower)", "Consumer group A"], ["Broker 3 (P2 leader, P0 follower)", "Consumer group B"]],
       "Same key → same partition → ordered. Each consumer group gets every message; within a group each partition is read by one consumer."),
  SEQ("Produce with acks=all, then consume", ["Producer", "Leader P0", "Follower P0", "Consumer"],
      [["Producer", "Leader P0", "batch of 500 msgs (compressed)", "", "Batching amortises network and disk cost; idempotent producer ids + sequence numbers stop duplicates on retry."],
       ["Leader P0", "Leader P0", "append to segment file (sequential write, page cache)"], ["Follower P0", "Leader P0", "fetch from offset 1,203,400"], ["Leader P0", "Follower P0", "records", "r"],
       ["Leader P0", "Producer", "ack when all in-sync replicas have it", "r", "min.insync.replicas = 2 means a write survives one broker loss."],
       ["Consumer", "Leader P0", "fetch from my offset 1,203,000", "", "Data goes from page cache to the socket with sendfile (zero-copy)."], ["Consumer", "Consumer", "process, then commit offset", "", "Commit after processing = at-least-once; commit before = at-most-once."]]),
  TABLE("Guarantees", ["Setting", "Effect"], [["acks=all + min.insync.replicas=2", "no loss if one broker dies"], ["idempotent producer", "no duplicates from producer retries"], ["transactions", "exactly-once read-process-write between topics"],
                                            ["retention by time/size", "old segments deleted as whole files"], ["log compaction", "keep only the latest value per key (changelog topics)"]]))

X("maps-hld",
  P("""**What the system does.** Shows the map, finds places, and computes the fastest route with live traffic and an accurate ETA, at ~50k route requests per second. Three subsystems: **map tiles** (pre-rendered, cached on a CDN), **routing** on a huge road graph (made fast by precomputed hierarchies), and **traffic** from millions of phones' location pings."""),
  AN("Planning a long drive with a road atlas: you don't check every village lane; you get onto the highway system near home, travel on highways, and only leave them near the destination. Contraction hierarchies precompute that 'highway' structure for the whole graph."),
  FLOW("Map tiles: a quadtree per zoom level", [["zoom 0: 1 tile (whole world)"], ["zoom 1: 4 tiles", "…"], ["zoom 2: 16 tiles", "zoom z: 4^z tiles"], ["x:CDN (tiles by z/x/y)"]],
       [["zoom 0: 1 tile (whole world)", "zoom 1: 4 tiles", "split ×4"], ["zoom 1: 4 tiles", "zoom 2: 16 tiles", "split ×4"], ["zoom 2: 16 tiles", "CDN (tiles by z/x/y)"], ["zoom z: 4^z tiles", "CDN (tiles by z/x/y)"]],
       "Tiles are pre-rendered (or vector tiles drawn on the device) and addressed as /z/x/y.png, perfect for CDN caching."),
  SEQ("Route request", ["App", "Routing service", "Routing graph (CH)", "Live traffic store"],
      [["App", "Routing service", "route from A to B, now"], ["Routing service", "Routing service", "snap A and B to the nearest road segments"],
       ["Routing service", "Routing graph (CH)", "bidirectional search going 'up' the hierarchy from both ends", "", "Explores thousands of nodes instead of millions."],
       ["Routing service", "Live traffic store", "current speeds on candidate segments", "", "Traffic = phones' pings map-matched to segments, averaged over the last few minutes."],
       ["Routing service", "App", "route polyline + ETA + alternatives", "r"], ["App", "Routing service", "location pings during navigation", "a", "Used for traffic and for rerouting if a faster path appears."]]),
  CALC("Sizing", [("Route requests", "50e3", "/s"), ("Pings from navigating users (10 M navigating, 1 per 5 s)", "10e6 / 5", "/s"), ("Tiles at zoom 18 (world)", "4 ** 18", "", "most never requested; render on demand + cache")]))

X("zoom-hld",
  P("""**What the system does.** Real-time audio and video between participants with ~150 ms latency. Media goes over **UDP** (late packets are useless, so no retransmission waits). The key architecture choice is how streams flow: **peer-to-peer mesh**, an **SFU** that forwards streams, or an **MCU** that mixes them. Large meetings use SFUs."""),
  AN("A conference call with a switchboard (SFU): each person speaks into the switchboard once, and the switchboard forwards each voice to whoever needs it, choosing the low-quality copy for people with bad connections. Nobody has to send their voice separately to everyone (mesh), and the switchboard doesn't have to mix voices itself (MCU)."),
  CALC("Bandwidth per participant in a 10-person meeting", [("Mesh: upload (send to 9 others at 1.5 Mbps)", "9 * 1.5", "Mbps"), ("SFU: upload (one stream with 3 simulcast layers)", "1.5 + 0.5 + 0.15", "Mbps"),
                                                           ("SFU: download (9 streams, mostly low layer)", "1.5 + 8 * 0.3", "Mbps")]),
  FLOW("SFU topology", [["u:Participant A", "u:Participant B", "u:Participant C"], ["SFU media servers (regional)"], ["Recording service"]],
       [["Participant A", "SFU media servers (regional)", "1 upload (simulcast)"], ["SFU media servers (regional)", "Participant B", "A's stream"], ["SFU media servers (regional)", "Participant C", "A's stream (low layer)"], ["SFU media servers (regional)", "Recording service", "bot participant"]]),
  SEQ("Joining a meeting", ["Client", "Signalling service", "STUN/TURN", "SFU"],
      [["Client", "Signalling service", "join meeting 123 (auth)"], ["Signalling service", "Client", "SFU address + ICE servers", "r"], ["Client", "STUN/TURN", "discover public address (NAT traversal)", "", "If UDP is blocked, media is relayed through TURN over TCP/443 (slower but works)."],
       ["Client", "SFU", "SDP offer/answer, DTLS-SRTP keys", "", "Encrypted media over UDP."], ["Client", "SFU", "upload video in 3 resolutions (simulcast)"], ["SFU", "Client", "forward others' streams at the layer my bandwidth allows", "r", "The SFU picks layers per receiver from bandwidth estimates; no transcoding."]]),
  TABLE("Mesh vs SFU vs MCU", ["", "Mesh (P2P)", "SFU", "MCU"], [["server cost", "none", "low (forwarding)", "high (decode + mix + encode)"], ["client upload", "N − 1 streams", "1 stream", "1 stream"], ["max size", "3–4", "hundreds", "large, lower quality"], ["latency", "lowest", "low", "higher"]]))

X("spotify-hld",
  P("""**What the system does.** Streams any of 100 million songs instantly, works offline, builds playlists and recommendations, and counts plays accurately enough to **pay royalties**. Audio files are small compared with video, so the challenges are **instant start** (prefetching and caching), **catalogue search**, and **trustworthy play counting**."""),
  AN("A record shop that guesses what you'll play next and puts it in your bag before you ask (prefetch), keeps your favourites at home (offline cache), and logs every play in a ledger used to pay the artists."),
  CALC("Sizing", [("Catalogue audio (100 M songs × 5 MB × 4 bitrates)", "100e6 * 5e6 * 4", "B"), ("Plays per second", "p = 1e9 / 86400", "/s"), ("Egress at ~4 MB per play", "p * 4e6", "B/s")]),
  SEQ("Pressing play", ["App", "API", "CDN", "Kafka"],
      [["App", "API", "play track T"], ["API", "App", "signed CDN URLs for T's chunks + license", "r"], ["App", "CDN", "GET first chunk (96 kbps for a fast start)", "", "Bitrate rises once the buffer is healthy; the next track in the queue is prefetched."],
       ["App", "Kafka", "PlayStarted / Played30s {eventId}", "a", "A stream counts for royalties after 30 s; event ids dedupe retries."],
       NOTE(["App", "Kafka"], "nightly: batch jobs compute royalties and update recommendation models from the play log")]),
  TABLE("Data", ["Data", "Store"], [["catalogue (tracks, albums, artists)", "SQL/Cassandra + search index"], ["playlists", "Cassandra (playlist id → ordered entries); collaborative editing via versioning"],
                                   ["audio", "object storage + CDN, DRM-encrypted for offline"], ["play events", "Kafka → data warehouse"], ["recommendations", "offline models (collaborative filtering, embeddings) → precomputed per user"]]))
